// src/utils/password.ts
var ITERATIONS = 1e5;
var KEY_LENGTH = 32;
var SALT_LENGTH = 16;
var encoder = new TextEncoder();
function bufToHex(buf) {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
function hexToBuf(hex3) {
  const arr = new Uint8Array(hex3.length / 2);
  for (let i = 0; i < hex3.length; i += 2) {
    arr[i / 2] = parseInt(hex3.slice(i, i + 2), 16);
  }
  return arr;
}
async function hashPassword(password) {
  const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
  const keyMaterial = await crypto.subtle.importKey("raw", encoder.encode(password), "PBKDF2", false, [
    "deriveBits"
  ]);
  const derived = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt,
      iterations: ITERATIONS,
      hash: "SHA-256"
    },
    keyMaterial,
    KEY_LENGTH * 8
  );
  return `pbkdf2$${ITERATIONS}$${bufToHex(salt.buffer)}$${bufToHex(derived)}`;
}
async function verifyPassword(password, stored) {
  const parts = stored.split("$");
  if (parts.length !== 4 || parts[0] !== "pbkdf2") {
    if (stored.startsWith("$2")) {
      return false;
    }
    return false;
  }
  const iterations = parseInt(parts[1], 10);
  const salt = hexToBuf(parts[2]);
  const storedHash = parts[3];
  const keyMaterial = await crypto.subtle.importKey("raw", encoder.encode(password), "PBKDF2", false, [
    "deriveBits"
  ]);
  const derived = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt,
      iterations,
      hash: "SHA-256"
    },
    keyMaterial,
    KEY_LENGTH * 8
  );
  const derivedHex = bufToHex(derived);
  if (derivedHex.length !== storedHash.length)
    return false;
  let diff = 0;
  for (let i = 0; i < derivedHex.length; i++) {
    diff |= derivedHex.charCodeAt(i) ^ storedHash.charCodeAt(i);
  }
  return diff === 0;
}

