debtsRoute.openapi(payRoute, async (c) => {
  const supabase = getSupabase(c.env);
  const businessId = c.get("businessId");
  const userId = c.get("userId");
  const { id } = c.req.valid("param");
  try {
    const { amount, payment_method, notes } = c.req.valid("json");
    const { data: debt } = await supabase.from("debts").select("*").eq("id", id).eq("business_id", businessId).single();
    if (!debt)
      return c.json({ success: false, error: { message: "Data tidak ditemukan" } }, 404);
    const currentRemaining = parseFloat(debt.remaining_amount);
    const currentAmount = parseFloat(debt.amount);
    if (debt.status === "paid" || currentRemaining <= 0) {
      return c.json({ success: false, error: { message: "Tagihan sudah lunas" } }, 400);
    }
    let paymentAmount = amount;
    if (paymentAmount > currentRemaining) {
      return c.json({ success: false, error: { message: `Jumlah pembayaran (Rp ${paymentAmount.toLocaleString("id-ID")}) melebihi sisa tagihan (Rp ${currentRemaining.toLocaleString("id-ID")})` } }, 400);
    }
    const newRemaining = currentRemaining - paymentAmount;
    let newStatus = debt.status;
    if (newRemaining <= 0)
      newStatus = "paid";
    else if (newRemaining < currentAmount)
      newStatus = "partial";
    await supabase.from("debt_payments").insert({
      debt_id: id,
      amount: paymentAmount.toString(),
      payment_method: payment_method || "cash",
      notes: notes || null,
      created_by: userId
    });
    const { data: updatedDebt } = await supabase.from("debts").update({ remaining_amount: newRemaining.toString(), status: newStatus, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id).select().single();
    return c.json({ success: true, data: updatedDebt }, 200);
  } catch (err) {
    return c.json({ success: false, error: { message: "Gagal menyimpan pembayaran" } }, 400);
  }
});

