purchasesRoute.openapi(createRouteDef9, async (c) => {
  const supabase = getSupabase(c.env);
  const businessId = c.get("businessId");
  const userId = c.get("userId");
  try {
    const body = c.req.valid("json");
    const { warehouse_id, supplier_id, expected_date, notes, items } = body;
    const { data: wh, error: whErr } = await supabase.from("warehouses").select("id").eq("id", warehouse_id).eq("business_id", businessId).single();
    if (whErr || !wh)
      throw new Error("Gudang tidak valid atau bukan milik bisnis ini");
    const { data: sup, error: supErr } = await supabase.from("suppliers").select("id").eq("id", supplier_id).eq("business_id", businessId).single();
    if (supErr || !sup)
      throw new Error("Supplier tidak valid atau bukan milik bisnis ini");
    const productIds = items.map((i) => i.product_id);
    if (productIds.length > 0) {
      const { data: validProducts, error: vpErr } = await supabase.from("products").select("id").eq("business_id", businessId).in("id", productIds);
      if (vpErr || !validProducts || validProducts.length !== productIds.length) {
        throw new Error("Terdapat produk yang tidak valid atau bukan milik bisnis ini");
      }
    }
    const { count } = await supabase.from("purchase_orders").select("*", { count: "exact", head: true }).eq("business_id", businessId);
    const nextId = (count || 0) + 1;
    const poNumber = `PO/${(/* @__PURE__ */ new Date()).getFullYear()}/${(/* @__PURE__ */ new Date()).getMonth() + 1}/${String(nextId).padStart(4, "0")}`;
    let totalAmount = 0;
    for (const item of items)
      totalAmount += item.qty * item.cost_price;
    const { data: po, error: poError } = await supabase.from("purchase_orders").insert({
      business_id: businessId,
      warehouse_id,
      supplier_id,
      po_number: poNumber,
      status: "draft",
      total_amount: totalAmount.toString(),
      expected_date: expected_date ? new Date(expected_date).toISOString() : null,
      notes: notes || null,
      created_by: userId
    }).select().single();
    if (poError || !po)
      throw poError || new Error("Gagal membuat PO");
    if (items.length > 0) {
      await supabase.from("purchase_order_items").insert(
        items.map((item) => ({
          po_id: po.id,
          product_id: item.product_id,
          qty: item.qty,
          cost_price: item.cost_price.toString()
        }))
      );
    }
    return c.json({ success: true, data: po }, 201);
  } catch (err) {
    return c.json({ success: false, error: { message: err.message || "Gagal menyimpan PO" } }, 400);
  }
});
purchasesRoute.patch("/:id/status", requirePermission("purchases.manage"));
purchasesRoute.openapi(updateStatusRouteDef2, async (c) => {
  const supabase = getSupabase(c.env);
  const businessId = c.get("businessId");
  const { id } = c.req.valid("param");
  try {
    const { status } = c.req.valid("json");
    if (status === "received") {
      const { data: result, error: rpcErr } = await supabase.rpc("receive_purchase_order", {
        p_po_id: id,
        p_business_id: businessId
      });
      if (rpcErr) {
        const msg = rpcErr.message || "";
        if (msg.includes("tidak ditemukan"))
          return c.json({ success: false, error: { message: "PO tidak ditemukan" } }, 404);
        if (msg.includes("sudah diterima"))
          return c.json({ success: false, error: { message: msg } }, 400);
        throw rpcErr;
      }
      return c.json({ success: true, data: result }, 200);
    }
    const { data: po } = await supabase.from("purchase_orders").select("*").eq("id", id).eq("business_id", businessId).single();
    if (!po)
      return c.json({ success: false, error: { message: "PO tidak ditemukan" } }, 404);
    if (po.status === "received")
      return c.json({ success: false, error: { message: "PO yang sudah diterima tidak dapat diubah statusnya" } }, 400);
    const { data: updatedPo } = await supabase.from("purchase_orders").update({ status, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id).select().single();
    return c.json({ success: true, data: updatedPo }, 200);
  } catch (err) {
    return c.json({ success: false, error: { message: "Gagal mengupdate status PO" } }, 400);
  }
});

