var ACCESS_TOKEN_TTL = 60 * 60 * 8;
var REFRESH_TOKEN_TTL = 60 * 60 * 24 * 30;
async function signTokenPair(c, payload) {
  const accessToken = await sign2(
    { ...payload, type: "access", exp: Math.floor(Date.now() / 1e3) + ACCESS_TOKEN_TTL },
    getEnv(c, "JWT_SECRET"),
    "HS256"
  );
  const refreshToken = await sign2(
    { ...payload, type: "refresh", exp: Math.floor(Date.now() / 1e3) + REFRESH_TOKEN_TTL },
    getEnv(c, "JWT_SECRET"),
    "HS256"
  );
  return { accessToken, refreshToken };
}
