authRoute.openapi(refreshRoute, async (c) => {
  const supabase = getSupabase(c.env);
  const { refresh_token } = c.req.valid("json");
  try {
    const decoded = await verify2(refresh_token, getEnv(c, "JWT_SECRET"), "HS256");
    if (!decoded || decoded.type !== "refresh" || !decoded.userId) {
      return c.json({ success: false, error: { code: "INVALID_REFRESH", message: "Refresh token tidak valid" } }, 401);
    }
    const { data: user } = await supabase.from("users").select("id, business_id, roles(permissions)").eq("id", decoded.userId).single();
    if (!user) {
      return c.json({ success: false, error: { code: "INVALID_REFRESH", message: "Sesi tidak valid" } }, 401);
    }
    const permissions = user.roles?.permissions || [];
    const accessToken = await sign2(
      {
        userId: user.id,
        businessId: user.business_id,
        roleId: decoded.roleId,
        type: "access",
        exp: Math.floor(Date.now() / 1e3) + ACCESS_TOKEN_TTL
      },
      getEnv(c, "JWT_SECRET"),
      "HS256"
    );
    return c.json({ success: true, data: { token: accessToken, permissions } }, 200);
  } catch (err) {
    return c.json({ success: false, error: { code: "INVALID_REFRESH", message: "Refresh token tidak valid atau telah kedaluwarsa" } }, 401);
  }
});
