async function checkAndIncrementAiUsage(supabase, businessId) {
  const { data: biz, error: error51 } = await supabase.from("businesses").select("settings").eq("id", businessId).single();
  if (error51 || !biz)
    return false;
  const settings = biz.settings || {};
  const today = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
  const aiUsage = settings.aiUsage || { date: today, count: 0 };
  if (aiUsage.date !== today) {
    aiUsage.date = today;
    aiUsage.count = 0;
  }
  if (aiUsage.count >= 10) {
    return false;
  }
  aiUsage.count += 1;
  settings.aiUsage = aiUsage;
  await supabase.from("businesses").update({ settings }).eq("id", businessId);
  return true;
}
async function callGemini(apiKey, prompt) {
  const url3 = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
  const response = await fetch(url3, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 500, temperature: 0.7 }
    })
  });
  if (!response.ok) {
    const errorText = await response.text();
    console.error("Gemini API Error:", errorText);
    throw new Error("Gagal menghubungi Gemini API");
  }
  const data = await response.json();
  return data?.candidates?.[0]?.content?.parts?.[0]?.text || "Tidak ada balasan dari AI.";
}
