// src/middleware/rateLimit.ts
var generalRateLimitCache = /* @__PURE__ */ new Map();
var authRateLimitCache = /* @__PURE__ */ new Map();
var rateLimitMiddleware = async (c, next) => {
  const ip = c.req.header("cf-connecting-ip") || c.req.header("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";
  const path = c.req.path;
  const now = Date.now();
  if (path === "/auth/login" || path === "/auth/register") {
    try {
      const reqClone = c.req.raw.clone();
      const body = await reqClone.json();
      const phone = body?.phone || "unknown";
      const key = `rl:auth:${ip}:${phone}`;
      const kv = c.env.RATE_LIMIT_KV;
      if (kv) {
        const recordStr = await kv.get(key);
        let record2 = recordStr ? JSON.parse(recordStr) : null;
        if (!record2 || now > record2.resetAt) {
          record2 = { count: 1, resetAt: now + 15 * 60 * 1e3 };
        } else {
          if (record2.count >= 5) {
            return c.json({
              success: false,
              error: { message: "Terlalu banyak percobaan, coba lagi dalam beberapa menit" }
            }, 429);
          }
          record2.count += 1;
        }
        const ttl = Math.max(60, Math.floor((record2.resetAt - now) / 1e3));
        await kv.put(key, JSON.stringify(record2), { expirationTtl: ttl });
      } else {
        let record2 = authRateLimitCache.get(key);
        if (!record2 || now > record2.resetAt) {
          record2 = { count: 1, resetAt: now + 15 * 60 * 1e3 };
        } else {
          if (record2.count >= 5) {
            return c.json({
              success: false,
              error: { message: "Terlalu banyak percobaan, coba lagi dalam beberapa menit" }
            }, 429);
          }
          record2.count += 1;
        }
        authRateLimitCache.set(key, record2);
      }
    } catch (e) {
      console.error("Rate limit auth error:", e);
    }
  } else {
    const key = `rl:gen:${ip}`;
    let record2 = generalRateLimitCache.get(key);
    if (!record2 || now > record2.resetAt) {
      record2 = { count: 1, resetAt: now + 60 * 1e3 };
    } else {
      if (record2.count >= 100) {
        return c.json({
          success: false,
          error: { message: "Terlalu banyak permintaan, coba lagi dalam beberapa menit" }
        }, 429);
      }
      record2.count += 1;
    }
    generalRateLimitCache.set(key, record2);
    if (Math.random() < 0.01) {
      for (const [k, v] of generalRateLimitCache.entries()) {
        if (now > v.resetAt)
          generalRateLimitCache.delete(k);
      }
      for (const [k, v] of authRateLimitCache.entries()) {
        if (now > v.resetAt)
          authRateLimitCache.delete(k);
      }
    }
  }
  await next();
};

